1	/* Milestone 1: the complete core red-black tree -- rb_create, rb_insert
2	 * with rotations and CLRS-style insert fixup, rb_find, rb_destroy,
3	 * rb_size, rb_validate, and rb_foreach. rb_delete (and its delete-fixup)
4	 * is Milestone 2 and keeps its minimal, honest stub below.
5	 *
6	 * Leaf representation: a missing child is NULL, permanently -- there is no
7	 * shared sentinel node. NULL is treated as black for all red-black color
8	 * logic (see color_of()); rotations/fixup/validate all check for NULL
9	 * rather than dereference a sentinel's color field.
10	 */
11	#include "rbtree.h"
12	
13	#include <stdlib.h>
14	#include <string.h>
15	
16	enum rb_color { RB_RED, RB_BLACK };
17	
18	struct rb_node {
19	    char           *key;      /* owned copy, NUL-terminated */
20	    void           *value;    /* owned only if t->value_free != NULL */
21	    enum rb_color   color;    /* set RB_RED on insert; unused for logic this slice */
22	    struct rb_node *left;
23	    struct rb_node *right;
24	    struct rb_node *parent;   /* NULL for root */
25	};
26	
27	struct rbtree {
28	    struct rb_node   *root;       /* NULL when empty */
29	    size_t            size;
30	    rb_value_free_fn  value_free; /* may be NULL */
31	};
32	
33	/* Allocation seam: every malloc/free in this file routes through these so
34	 * a later slice (or a test harness) can hook allocation without touching
35	 * call sites. */
36	static void *rb_malloc(size_t n) { return malloc(n); }
37	static void  rb_free(void *p)    { free(p); }
38	
39	/* NULL counts as a black leaf everywhere in red-black logic, since there
40	 * is no sentinel node to hold a color. */
41	static enum rb_color color_of(const struct rb_node *n) { return n ? n->color : RB_BLACK; }
42	
43	/* Promotes x->right to x's place; x becomes its former right child's left
44	 * child. Order matters: capture the mover (y) first, migrate the orphaned
45	 * middle subtree next (read before overwrite), reparent y into the
46	 * grandparent slot (or root) third, link x under y last. */
47	static void rotate_left(rbtree_t *t, struct rb_node *x) {
48	    struct rb_node *y = x->right;
49	
50	    x->right = y->left;
51	    if (y->left != NULL) {
52	        y->left->parent = x;
53	    }
54	
55	    y->parent = x->parent;
56	    if (x->parent == NULL) {
57	        t->root = y;
58	    } else if (x == x->parent->left) {
59	        x->parent->left = y;
60	    } else {
61	        x->parent->right = y;
62	    }
63	
64	    y->left = x;
65	    x->parent = y;
66	}
67	
68	/* Mirror of rotate_left: promotes x->left to x's place. */
69	static void rotate_right(rbtree_t *t, struct rb_node *x) {
70	    struct rb_node *y = x->left;
71	
72	    x->left = y->right;
73	    if (y->right != NULL) {
74	        y->right->parent = x;
75	    }
76	
77	    y->parent = x->parent;
78	    if (x->parent == NULL) {
79	        t->root = y;
80	    } else if (x == x->parent->right) {
81	        x->parent->right = y;
82	    } else {
83	        x->parent->left = y;
84	    }
85	
86	    y->right = x;
87	    x->parent = y;
88	}
89	
90	/* Restores red-black properties after inserting red node z.
91	 * Loop invariant: z is red, and the only possible violation is a red-red
92	 * edge between z and z->parent -- every other red-black property holds. */
93	static void insert_fixup(rbtree_t *t, struct rb_node *z) {
94	    while (color_of(z->parent) == RB_RED) {
95	        if (z->parent == z->parent->parent->left) {
96	            struct rb_node *uncle = z->parent->parent->right;
97	            if (color_of(uncle) == RB_RED) {
98	                /* Case 1: uncle red -- recolor only, push violation up. */
99	                z->parent->color = RB_BLACK;
100	                uncle->color = RB_BLACK;
101	                z->parent->parent->color = RB_RED;
102	                z = z->parent->parent;
103	            } else {
104	                if (z == z->parent->right) {
105	                    /* Case 2: triangle -- rotate at parent to form a line. */
106	                    z = z->parent;
107	                    rotate_left(t, z);
108	                }
109	                /* Case 3: line -- recolor then rotate at grandparent. */
110	                z->parent->color = RB_BLACK;
111	                z->parent->parent->color = RB_RED;
112	                rotate_right(t, z->parent->parent);
113	            }
114	        } else {
115	            /* Mirror: parent is a right child; uncle is grandparent->left;
116	             * Case 2 uses rotate_right, Case 3 uses rotate_left. */
117	            struct rb_node *uncle = z->parent->parent->left;
118	            if (color_of(uncle) == RB_RED) {
119	                z->parent->color = RB_BLACK;
120	                uncle->color = RB_BLACK;
121	                z->parent->parent->color = RB_RED;
122	                z = z->parent->parent;
123	            } else {
124	                if (z == z->parent->left) {
125	                    z = z->parent;
126	                    rotate_right(t, z);
127	                }
128	                z->parent->color = RB_BLACK;
129	                z->parent->parent->color = RB_RED;
130	                rotate_left(t, z->parent->parent);
131	            }
132	        }
133	    }
134	    t->root->color = RB_BLACK;
135	}
