137	rbtree_t *rb_create(rb_value_free_fn value_free) {
138	    struct rbtree *t = rb_malloc(sizeof *t);
139	    if (t == NULL) {
140	        return NULL;
141	    }
142	
143	    t->root = NULL;
144	    t->size = 0;
145	    t->value_free = value_free;
146	    return t;
147	}
