149	int rb_insert(rbtree_t *t, const char *key, void *value) {
150	    if (t == NULL || key == NULL) {
151	        return -1;
152	    }
153	
154	    struct rb_node *parent = NULL;
155	    struct rb_node *cur = t->root;
156	    int cmp = 0;
157	
158	    /* cur descends the BST; parent trails one level behind; parent is
159	     * where the new node attaches if cur becomes NULL. */
160	    while (cur != NULL) {
161	        cmp = strcmp(key, cur->key);
162	        if (cmp == 0) {
163	            /* Overwrite path: same key reused verbatim, no allocation
164	             * is possible or needed on this path. */
165	            if (t->value_free != NULL) {
166	                t->value_free(cur->value);
167	            }
168	            cur->value = value;
169	            return 0;
170	        }
171	        parent = cur;
172	        cur = (cmp < 0) ? cur->left : cur->right;
173	    }
174	
175	    size_t keylen = strlen(key);
176	    char *keycopy = NULL;
177	    struct rb_node *node = NULL;
178	
179	    keycopy = rb_malloc(keylen + 1);
180	    if (keycopy == NULL) {
181	        goto fail;
182	    }
183	    memcpy(keycopy, key, keylen + 1);
184	
185	    node = rb_malloc(sizeof *node);
186	    if (node == NULL) {
187	        goto fail;
188	    }
189	
190	    node->key = keycopy;
191	    node->value = value;
192	    node->color = RB_RED;
193	    node->left = NULL;
194	    node->right = NULL;
195	    node->parent = parent;
196	
197	    if (parent == NULL) {
198	        node->color = RB_BLACK; /* redundant-but-harmless: insert_fixup's
199	                                  * tail line also guarantees this on every
200	                                  * call; kept as a self-documenting base
201	                                  * case for the empty-tree fast path. */
202	        t->root = node;
203	    } else if (cmp < 0) {
204	        parent->left = node;
205	    } else {
206	        parent->right = node;
207	    }
208	    insert_fixup(t, node);
209	    t->size++;
210	    return 0;
211	
212	fail:
213	    rb_free(keycopy);
214	    rb_free(node);
215	    return -1;
216	}
217	
218	void *rb_find(const rbtree_t *t, const char *key) {
219	    if (t == NULL || key == NULL) {
220	        return NULL;
221	    }
222	
223	    /* cur is the current candidate subtree root; the loop terminates on
224	     * a match or when a leaf (NULL child) is passed. */
225	    const struct rb_node *cur = t->root;
226	    while (cur != NULL) {
227	        int cmp = strcmp(key, cur->key);
228	        if (cmp == 0) {
229	            return cur->value;
230	        }
231	        cur = (cmp < 0) ? cur->left : cur->right;
232	    }
233	    return NULL;
234	}
