236	static void free_subtree(struct rb_node *n, rb_value_free_fn value_free) {
237	    if (n == NULL) {
238	        return;
239	    }
240	    free_subtree(n->left, value_free);
241	    free_subtree(n->right, value_free);
242	    rb_free(n->key);
243	    if (value_free != NULL) {
244	        value_free(n->value);
245	    }
246	    rb_free(n);
247	}
248	
249	void rb_destroy(rbtree_t *t) {
250	    if (t == NULL) {
251	        return;
252	    }
253	    free_subtree(t->root, t->value_free);
254	    rb_free(t);
255	}
256	
257	int rb_delete(rbtree_t *t, const char *key) {
258	    (void)t;
259	    (void)key;
260	    return -1;
261	}
262	
263	size_t rb_size(const rbtree_t *t) {
264	    if (t == NULL) {
265	        return 0;
266	    }
267	    return t->size;
268	}
