270	static void foreach_subtree(const struct rb_node *n,
271	                             void (*fn)(const char *key, void *value, void *ctx),
272	                             void *ctx) {
273	    if (n == NULL) {
274	        return;
275	    }
276	    foreach_subtree(n->left, fn, ctx);
277	    fn(n->key, n->value, ctx);
278	    foreach_subtree(n->right, fn, ctx);
279	}
280	
281	void rb_foreach(const rbtree_t *t,
282	                void (*fn)(const char *key, void *value, void *ctx),
283	                void *ctx) {
284	    if (t == NULL || fn == NULL) {
285	        return;
286	    }
287	    foreach_subtree(t->root, fn, ctx);
288	}
289	
290	#define RB_INVALID (-1)
291	
292	/* Returns the subtree's black-height on success, RB_INVALID if any
293	 * red-black invariant, BST-ordering rule, or parent-pointer link is
294	 * violated anywhere in it. lo/hi are exclusive bounds inherited from
295	 * ancestor keys, NULL meaning unbounded. *count is incremented once per
296	 * visited node, so the caller can cross-check it against t->size
297	 * (Invariant 5, Section 9). */
298	static int validate_subtree(const struct rb_node *n, const struct rb_node *parent,
299	                             const char *lo, const char *hi, size_t *count) {
300	    if (n == NULL) {
301	        return 0;
302	    }
303	    (*count)++;
304	    if (n->parent != parent) {
305	        return RB_INVALID;
306	    }
307	    if ((lo != NULL && strcmp(n->key, lo) <= 0) ||
308	        (hi != NULL && strcmp(n->key, hi) >= 0)) {
309	        return RB_INVALID;
310	    }
311	    if (n->color == RB_RED &&
312	        (color_of(n->left) == RB_RED || color_of(n->right) == RB_RED)) {
313	        return RB_INVALID;
314	    }
315	
316	    int lbh = validate_subtree(n->left, n, lo, n->key, count);
317	    if (lbh == RB_INVALID) {
318	        return RB_INVALID;
319	    }
320	    int rbh = validate_subtree(n->right, n, n->key, hi, count);
321	    if (rbh == RB_INVALID || rbh != lbh) {
322	        return RB_INVALID;
323	    }
324	
325	    return lbh + (n->color == RB_BLACK ? 1 : 0);
326	}
327	
328	int rb_validate(const rbtree_t *t) {
329	    if (t == NULL) {
330	        return 0; /* consistent with rb_size/rb_find: NULL means "empty" */
331	    }
332	    if (t->root != NULL && (t->root->parent != NULL || t->root->color != RB_BLACK)) {
333	        return -1;
334	    }
335	    size_t count = 0;
336	    if (validate_subtree(t->root, NULL, NULL, NULL, &count) == RB_INVALID) {
337	        return -1;
338	    }
339	    return count == t->size ? 0 : -1;
340	}
