#include "rbtree.h"
#include <stdio.h>
#include <string.h>

extern int case_hits[8];
void rb_debug_dump(const rbtree_t *t);

static void run_scenario(const char *label, const char **ins, int nins,
                          const char **dels, int ndels) {
    memset(case_hits, 0, sizeof(int) * 8);
    rbtree_t *t = rb_create(NULL);
    for (int i = 0; i < nins; i++) {
        rb_insert(t, ins[i], NULL);
    }
    printf("=== %s === (validate after build = %d)\n", label, rb_validate(t));
    rb_debug_dump(t);
    for (int i = 0; i < ndels; i++) {
        int rc = rb_delete(t, dels[i]);
        printf("delete(%s) rc=%d validate=%d\n", dels[i], rc, rb_validate(t));
    }
    rb_debug_dump(t);
    printf("case_hits: c1L=%d c2L=%d c3L=%d c4L=%d c1R=%d c2R=%d c3R=%d c4R=%d\n\n",
           case_hits[0], case_hits[1], case_hits[2], case_hits[3],
           case_hits[4], case_hits[5], case_hits[6], case_hits[7]);
    rb_destroy(t);
}

int main(void) {
    {
        const char *ins[] = {"b", "a", "c", "d"};
        const char *dels[] = {"a"};
        run_scenario("case4-left isolated", ins, 4, dels, 1);
    }
    {
        const char *ins[] = {"c", "d", "b", "a"};
        const char *dels[] = {"d"};
        run_scenario("case4-right isolated", ins, 4, dels, 1);
    }
    {
        const char *ins[] = {"d", "b", "f", "a", "c", "e", "g"};
        const char *dels[] = {"a", "c", "e", "g", "b"};
        run_scenario("case2-left isolated", ins, 7, dels, 5);
    }
    {
        const char *ins[] = {"d", "b", "f", "a", "c", "e", "g"};
        const char *dels[] = {"a", "c", "e", "g", "f"};
        run_scenario("case2-right isolated", ins, 7, dels, 5);
    }
    {
        const char *ins[] = {"d", "b", "f", "a", "c", "e", "g", "h"};
        const char *dels[] = {"e"};
        run_scenario("probe case1-left target", ins, 8, dels, 1);
    }
    return 0;
}

